// Generates src/generated/ from the committed snapshot of the published OpenAPI document.
//
//   node scripts/generate.mjs           write the generated files
//   node scripts/generate.mjs --check   fail if the committed files differ from a fresh run
//
// Enums that an answer can reach are made open ("buy" | "sell" | (string & {})), so a value the API
// adds later is still a valid answer. Enums in request bodies stay closed, so a typo is a type error.
// A schema used on both sides is emitted twice: closed under its own name, open as `<Name>Open`.

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";
import ts from "typescript";

const root = fileURLToPath(new URL("..", import.meta.url));
const snapshotPath = `${root}openapi.json`;
const schemaPath = `${root}src/generated/schema.ts`;
const tablesPath = `${root}src/generated/tables.ts`;

const HEADER = "// Generated by scripts/generate.mjs from openapi.json. Do not edit.\n";
const REF_PREFIX = "#/components/schemas/";
const METHODS = ["get", "put", "post", "delete", "patch"];

const check = process.argv.includes("--check");
const document = JSON.parse(await readFile(snapshotPath, "utf8"));

const prepared = prepare(document);
const schema = HEADER + (await renderSchema(prepared));
const tables = HEADER + renderTables(document);

if (check) {
  const stale = [];
  for (const [path, fresh] of [
    [schemaPath, schema],
    [tablesPath, tables],
  ]) {
    const committed = await readFile(path, "utf8").catch(() => "");
    if (committed !== fresh) stale.push(path.slice(root.length));
  }
  if (stale.length > 0) {
    console.error(`Generated code is stale: ${stale.join(", ")}. Run pnpm generate and commit the result.`);
    process.exit(1);
  }
  console.log("Generated code is fresh.");
} else {
  await writeFile(schemaPath, schema);
  await writeFile(tablesPath, tables);
  console.log("Wrote src/generated/schema.ts and src/generated/tables.ts.");
}

/** Every `$ref` to a component schema under `node`. */
function refsIn(node, found = new Set()) {
  if (Array.isArray(node)) {
    for (const item of node) refsIn(item, found);
  } else if (node && typeof node === "object") {
    for (const [key, value] of Object.entries(node)) {
      if (key === "$ref" && typeof value === "string" && value.startsWith(REF_PREFIX)) {
        found.add(value.slice(REF_PREFIX.length));
      } else {
        refsIn(value, found);
      }
    }
  }
  return found;
}

/** The component schemas reachable from `roots`, following refs. */
function reachable(roots, schemas) {
  const seen = new Set();
  const queue = [...refsIn(roots)];
  while (queue.length > 0) {
    const name = queue.pop();
    if (seen.has(name)) continue;
    seen.add(name);
    queue.push(...refsIn(schemas[name]));
  }
  return seen;
}

function hasEnum(node) {
  if (Array.isArray(node)) return node.some(hasEnum);
  if (!node || typeof node !== "object") return false;
  return Array.isArray(node.enum) || Object.values(node).some(hasEnum);
}

function rewriteRefs(node, renames) {
  if (Array.isArray(node)) return node.map((item) => rewriteRefs(item, renames));
  if (!node || typeof node !== "object") return node;
  const out = {};
  for (const [key, value] of Object.entries(node)) {
    if (key === "$ref" && typeof value === "string" && value.startsWith(REF_PREFIX)) {
      const name = value.slice(REF_PREFIX.length);
      out[key] = renames.has(name) ? REF_PREFIX + renames.get(name) : value;
    } else {
      out[key] = rewriteRefs(value, renames);
    }
  }
  return out;
}

function markOpen(node) {
  if (Array.isArray(node)) return node.map(markOpen);
  if (!node || typeof node !== "object") return node;
  const out = {};
  for (const [key, value] of Object.entries(node)) out[key] = markOpen(value);
  if (Array.isArray(node.enum)) out["x-open"] = true;
  return out;
}

function operations(doc) {
  const list = [];
  for (const [path, item] of Object.entries(doc.paths)) {
    for (const method of METHODS) {
      if (item[method]) list.push({ path, method, operation: item[method] });
    }
  }
  return list;
}

/** The document as the generator should see it: answer-side enums open, request-side closed. */
function prepare(source) {
  const doc = structuredClone(source);
  const schemas = doc.components.schemas;
  const answerRoots = [];
  const requestRoots = [];
  for (const { operation } of operations(doc)) {
    answerRoots.push(operation.responses);
    requestRoots.push(operation.requestBody ?? null, operation.parameters ?? null);
  }
  for (const item of Object.values(doc.paths)) requestRoots.push(item.parameters ?? null);

  const answers = reachable(answerRoots, schemas);
  const requests = reachable(requestRoots, schemas);
  const shared = [...answers].filter((name) => requests.has(name) && hasEnum(schemas[name]));
  const renames = new Map(shared.map((name) => [name, `${name}Open`]));
  for (const name of shared) {
    if (schemas[renames.get(name)]) throw new Error(`The document already has a schema named ${renames.get(name)}`);
  }

  for (const name of shared) {
    schemas[renames.get(name)] = markOpen(rewriteRefs(schemas[name], renames));
  }
  for (const name of answers) {
    if (!requests.has(name)) schemas[name] = markOpen(rewriteRefs(schemas[name], renames));
  }
  for (const { operation } of operations(doc)) {
    operation.responses = markOpen(rewriteRefs(operation.responses, renames));
  }
  return doc;
}

function resolvePointer(doc, pointer) {
  if (!pointer?.startsWith("#/")) return undefined;
  let node = doc;
  for (const raw of pointer.slice(2).split("/")) {
    const key = raw.replaceAll("~1", "/").replaceAll("~0", "~");
    if (!node || typeof node !== "object" || !(key in node)) return undefined;
    node = node[key];
  }
  return node;
}

async function renderSchema(doc) {
  const opened = new Set();
  const openString = ts.factory.createIntersectionTypeNode([
    ts.factory.createKeywordTypeNode(ts.SyntaxKind.StringKeyword),
    ts.factory.createTypeLiteralNode([]),
  ]);
  const open = (type) => {
    const members = ts.isUnionTypeNode(type) ? [...type.types] : [type];
    return ts.factory.createUnionTypeNode([...members, openString]);
  };
  // Named schemas (such as `FillingOpen`) pass through postTransform; enums inline in an object's
  // properties pass through transformProperty instead.
  const ast = await openapiTS(doc, {
    silent: true,
    postTransform(type, options) {
      const node = resolvePointer(doc, options.path);
      if (!node?.["x-open"]) return undefined;
      opened.add(options.path);
      return open(type);
    },
    transformProperty(property, schemaObject, options) {
      const where = `${options.path}/properties/${property.name.text}`;
      let type;
      if (schemaObject["x-open"]) {
        type = open(property.type);
      } else if (schemaObject.items?.["x-open"] && ts.isArrayTypeNode(property.type)) {
        let element = property.type.elementType;
        if (ts.isParenthesizedTypeNode(element)) element = element.type;
        type = ts.factory.createArrayTypeNode(ts.factory.createParenthesizedType(open(element)));
      } else {
        return undefined;
      }
      opened.add(where);
      return ts.factory.updatePropertySignature(
        property,
        property.modifiers,
        property.name,
        property.questionToken,
        type,
      );
    },
  });
  const marked = countOpen(doc);
  if (opened.size !== marked) {
    throw new Error(`${opened.size} of ${marked} answer enums were made open; check the generator.`);
  }
  return astToString(ast);
}

function countOpen(node) {
  if (Array.isArray(node)) return node.reduce((sum, item) => sum + countOpen(item), 0);
  if (!node || typeof node !== "object") return 0;
  const own = node["x-open"] ? 1 : 0;
  return own + Object.values(node).reduce((sum, value) => sum + countOpen(value), 0);
}

/** The error codes the document lists for an operation's refusals: in their examples or descriptions. */
function documentedCodes(operation, known) {
  const codes = new Set();
  for (const [status, response] of Object.entries(operation.responses)) {
    if (status.startsWith("2")) continue;
    for (const media of Object.values(response.content ?? {})) {
      for (const name of Object.keys(media.examples ?? {})) if (known.includes(name)) codes.add(name);
    }
    for (const match of (response.description ?? "").matchAll(/`([a-z_]+)`:/g)) {
      if (known.includes(match[1])) codes.add(match[1]);
    }
  }
  return [...codes].sort();
}

function renderTables(doc) {
  const extension = doc["x-pipsocket"];
  const errors = Object.fromEntries(extension.errors.map((e) => [e.code, e.status]));
  const retcodes = Object.fromEntries(extension.retcodes.map((r) => [r.code, r.name]));
  const ops = operations(doc).map(({ path, method, operation }) => ({
    operationId: operation.operationId,
    method: method.toUpperCase(),
    path,
    keyed: (operation.parameters ?? []).some((p) => p.in === "header" && p.name === "Idempotency-Key"),
    codes: documentedCodes(operation, Object.keys(errors)),
  }));
  const states = doc.components.schemas.RequestState.enum;
  const json = (value) => JSON.stringify(value, null, 2);
  return [
    "",
    "/** Every error code the API answers with, and its HTTP status. */",
    `export const ERROR_STATUS = ${json(errors)} as const;`,
    "",
    "export type ErrorCode = keyof typeof ERROR_STATUS;",
    "",
    "/** MT5's trade server return codes, by number, with the names the API sends in `retcode_name`. */",
    `export const RETCODE_NAMES: Readonly<Record<number, string>> = ${json(retcodes)};`,
    "",
    "/** Every operation in the document, with the error codes it documents for its refusals. */",
    `export const OPERATIONS = ${json(ops)} as const;`,
    "",
    'export type OperationId = (typeof OPERATIONS)[number]["operationId"];',
    "",
    "/** The states a recorded request can be in. */",
    `export const REQUEST_STATES = ${json(states)} as const;`,
    "",
    "export type RequestState = (typeof REQUEST_STATES)[number];",
    "",
  ].join("\n");
}
